pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(string calldata description) public {
        // Make caller an admin
        c.isAdmin(address(this));
        // Record the returned newOracle address
        address newOracle;
        // Capture the event to get newOracle address
        vm.recordLogs();
        c.newEmergencyOracle(description);
        Vm.Log[] memory entries = vm.getRecordedLogs();
        require(entries.length == 1, "expected one event");
        // Decode the event: NewEmergencyOracle(address owner, address newOracle)
        // We rely on the fact that it's emitted, and we know the indexed params layout.
        // The event has topic0 = keccak256("NewEmergencyOracle(address,address)")
        // For simplicity we directly decode the data and indexed param.
        (address emittedOwner, address emittedOracle) = abi.decode(entries[0].data, (address, address));
        newOracle = emittedOracle;
        // Assert: new oracle's owner is the caller (address(this))
        EmergencyOracle oracle = EmergencyOracle(newOracle);
        assertTrue(oracle.owner() == address(this));
    }
}

