contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, string calldata description) public {
        vm.assume(caller != address(0));
        vm.prank(caller);
        c.newEmergencyOracle(description);
        // C's nonce before this call was 1.
        address oracle = getAddress(address(c), 1);
        vm.prank(caller);
        (bool ok, ) = oracle.call(abi.encodeWithSignature("setAssetPrice(uint256)", uint256(0)));
        assertTrue(ok);
    }
    function getAddress(address sender, uint256 nonce) internal pure returns (address) {
        if (nonce == 0) {
            return address(uint160(uint256(keccak256(abi.encodePacked(bytes1(0xd6), bytes1(0x94), sender, bytes1(0x80))))));
        } else if (nonce < 0x80) {
            return address(uint160(uint256(keccak256(abi.encodePacked(bytes1(0xd6), bytes1(0x94), sender, bytes1(uint8(nonce)))))));
        } else {
            // Should not be needed for nonce 1, but we handle for completeness.
            // Actually, for nonce <= 0x7f it's the above. For nonce >= 0x80, it needs length encoding.
            // Since nonce is 1, it's fine.
