pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // Make this test contract an admin
        c.isAdmin(address(this)) = true;
    }

    function testFuzz_property(string calldata description) public {
        // Fuzz the description, keeping it unrestricted
        // The caller is this test contract, which is already an admin
        try c.newEmergencyOracle(description) returns (address newOracle) {
            // On success, retrieve the owner of the newly created EmergencyOracle
            // EmergencyOracle has a public owner() getter
            (bool ok, bytes memory data) = newOracle.call(abi.encodeWithSignature("owner()"));
            require(ok, "owner() call failed");
            address actualOwner = abi.decode(data, (address));
            // The general rule: the owner must equal the caller (address(this))
            assertTrue(actualOwner == address(this));
        } catch {
            // If the call reverts for some reason, we consider it passing (the property is vacuously true)
            assertTrue(true);
        }
    }
}

