        vm.recordLogs();
        c.newEmergencyOracle(description);
        Vm.Log[] memory logs = vm.getRecordedLogs();
        // Find the NewEmergencyOracle event
        bool found = false;
        for (uint i = 0; i < logs.length; i++) {
            if (logs[i].topics[0] == keccak256("NewEmergencyOracle(address,address)")) {
                (address eventOwner, address eventNewOracle) = abi.decode(logs[i].data, (address, address));
                // The general rule: the event's owner parameter must equal the actual owner of the created oracle.
                // The bug creates the oracle with owner address(0), so owner() will be address(0),
                // but the event's owner parameter is msg.sender (the caller).
                // We check that eventOwner == EmergencyOracle(eventNewOracle).owner().
                assertTrue(eventOwner == EmergencyOracle(eventNewOracle).owner());
                found = true;
                break;
            }
        }
        assertTrue(found);
    }
}

